const arr = Array.from({length: 500}, () => Math.floor(Math.random() * 1000));
let comparisons = 0;
for (let i = 0; i < arr.length; i++) {
  for (let j = 0; j < arr.length - 1; j++) {
    comparisons++;
    if (arr[j] > arr[j + 1]) {
      [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
    }
  }
}
console.log('bubble comparisons:', comparisons);
console.log('sorted correctly:', arr.every((v, i) => i === 0 || arr[i - 1] <= v));

